--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` varchar(20) NOT NULL,
  `customer_name` varchar(255) DEFAULT NULL,
  `customer_phone` varchar(50) DEFAULT NULL,
  `customer_address` text,
  `customer_username` varchar(50) DEFAULT NULL,
  `username` varchar(50) DEFAULT NULL,
  `cashier_name` varchar(255) DEFAULT NULL,
  `voucher_code` varchar(50) DEFAULT NULL,
  `amount_tendered` decimal(10,0) DEFAULT NULL,
  `total_amount` decimal(10,0) DEFAULT NULL,
  `discount_amount` decimal(10,0) DEFAULT NULL,
  `shipping_fee` decimal(10,0) DEFAULT NULL,
  `final_total` decimal(10,0) DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `order_type` varchar(50) DEFAULT NULL,
  `status` enum('pending','confirmed','completed','cancelled') DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_order_staff` (`username`),
  KEY `fk_order_customer` (`customer_username`),
  CONSTRAINT `fk_order_customer` FOREIGN KEY (`customer_username`) REFERENCES `users` (`username`) ON DELETE SET NULL,
  CONSTRAINT `fk_order_staff` FOREIGN KEY (`username`) REFERENCES `users` (`username`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

