INSERT INTO `products` VALUES (1,'8935015874068','Bộ 5 Bút Bi 0,5mm Queen 740-Mực Xanh',27000,'/products/sp2.jpg','but-viet','<p><strong>Bộ&nbsp;5&nbsp;Bút&nbsp;Bi&nbsp;Queen&nbsp;740</strong>&nbsp;được&nbsp;sản&nbsp;xuất&nbsp;theo&nbsp;công&nbsp;nghệ&nbsp;hiện&nbsp;đại,&nbsp;kiểu&nbsp;dáng&nbsp;phù&nbsp;hợp&nbsp;cho&nbsp;các&nbsp;cấp&nbsp;bậc&nbsp;học&nbsp;sinh,&nbsp;giáo&nbsp;viên,&nbsp;văn&nbsp;phòng…</p><p><strong><em>Thông&nbsp;số&nbsp;kĩ&nbsp;thuật:&nbsp;</em></strong></p><p>-&nbsp;Thương&nbsp;hiệu:&nbsp;Queen</p><p>-&nbsp;Đầu&nbsp;bi&nbsp;0.5&nbsp;mm,&nbsp;viết&nbsp;trơn&nbsp;êm,&nbsp;màu&nbsp;mực&nbsp;chuẩn,&nbsp;đậm,&nbsp;tươi,&nbsp;mực&nbsp;chảy&nbsp;lưu&nbsp;loát.</p><p>-&nbsp;Bút&nbsp;bi&nbsp;740&nbsp;được&nbsp;sản&nbsp;xuất&nbsp;theo&nbsp;công&nbsp;nghệ&nbsp;hiện&nbsp;đại.</p><p>-&nbsp;SXT&nbsp;TC&nbsp;07&nbsp;-&nbsp;2006&nbsp;/&nbsp;CTY&nbsp;TVP</p><p>-&nbsp;Công&nbsp;nghệ&nbsp;sản&nbsp;xuất&nbsp;Châu&nbsp;Âu&nbsp;tiên&nbsp;tiến</p><p>-&nbsp;Thiết&nbsp;kế&nbsp;đẹp,&nbsp;đơn&nbsp;giản&nbsp;,&nbsp;nhỏ&nbsp;gọn&nbsp;,&nbsp;rất&nbsp;chắc&nbsp;chắn&nbsp;,&nbsp;dễ&nbsp;cầm&nbsp;và&nbsp;chắc&nbsp;tay&nbsp;Lưu&nbsp;ý:&nbsp;Bấm&nbsp;bút&nbsp;lại&nbsp;sau&nbsp;khi&nbsp;sử&nbsp;dụng&nbsp;Bảo&nbsp;quản:&nbsp;Bảo&nbsp;quản&nbsp;nơi&nbsp;khô&nbsp;ráo,&nbsp;thoáng&nbsp;mát.</p>',150,'active'),(2,'8935015820010','Bút dạ quang Queen HL-02 (6 bút 2 màu vàng)',30000,'/products/sp4.jpg','but-viet','<p><strong>Bút&nbsp;dạ&nbsp;quang&nbsp;Queen&nbsp;HL-01&nbsp;-&nbsp;Hộp&nbsp;6&nbsp;bút&nbsp;(5&nbsp;màu,&nbsp;2&nbsp;màu&nbsp;vàng)</strong></p><p>&nbsp;<strong>Nhiều&nbsp;mực:</strong>&nbsp;Viết&nbsp;liên&nbsp;tục&nbsp;đến&nbsp;100&nbsp;mét,&nbsp;phù&nbsp;hợp&nbsp;cho&nbsp;nhu&nbsp;cầu&nbsp;học&nbsp;tập&nbsp;và&nbsp;làm&nbsp;việc&nbsp;dài&nbsp;hạn.</p><p>&nbsp;<strong>Màu&nbsp;mực&nbsp;nổi&nbsp;bật:</strong>&nbsp;Sắc&nbsp;nét,&nbsp;rõ&nbsp;ràng,&nbsp;giúp&nbsp;làm&nbsp;nổi&nbsp;bật&nbsp;thông&nbsp;tin&nbsp;quan&nbsp;trọng&nbsp;trên&nbsp;tài&nbsp;liệu.</p><p>&nbsp;<strong>Thiết&nbsp;kế&nbsp;siêu&nbsp;nhẹ:</strong>&nbsp;Dễ&nbsp;cầm,&nbsp;hạn&nbsp;chế&nbsp;mỏi&nbsp;tay&nbsp;khi&nbsp;sử&nbsp;dụng&nbsp;trong&nbsp;thời&nbsp;gian&nbsp;dài.</p><p>&nbsp;<strong>Ứng&nbsp;dụng&nbsp;đa&nbsp;dạng:</strong>&nbsp;Phù&nbsp;hợp&nbsp;cho&nbsp;học&nbsp;sinh,&nbsp;sinh&nbsp;viên,&nbsp;giáo&nbsp;viên&nbsp;và&nbsp;nhân&nbsp;viên&nbsp;văn&nbsp;phòng.</p><p>&nbsp;<strong>Chất&nbsp;lượng&nbsp;ổn&nbsp;định:</strong>&nbsp;Dòng&nbsp;mực&nbsp;đều,&nbsp;không&nbsp;lem,&nbsp;giữ&nbsp;trang&nbsp;tài&nbsp;liệu&nbsp;gọn&nbsp;gàng&nbsp;và&nbsp;sạch&nbsp;sẽ.</p><p>&nbsp;<strong><em>Bảo&nbsp;quản:</em></strong></p><p>&nbsp;-&nbsp;Bảo&nbsp;quản&nbsp;nơi&nbsp;khô&nbsp;ráo,&nbsp;thoáng&nbsp;mát.</p><p>&nbsp;-&nbsp;Tránh&nbsp;tiếp&nbsp;xúc&nbsp;với&nbsp;ánh&nbsp;nắng&nbsp;trực&nbsp;tiếp.</p><p>&nbsp;<strong><em>Khuyến&nbsp;cáo:</em></strong></p><p>&nbsp;-&nbsp;Đậy&nbsp;nắp&nbsp;ngay&nbsp;sau&nbsp;khi&nbsp;sử&nbsp;dụng.</p>',100,'active'),(3,'8935324017323','Combo 10 Bút chì gỗ nhân vật Akooland Thiên Long TP-GP021/AK - Mẫu ngẫu nhiên',50000,'/products/sp5.jpg','but-viet','<p><strong>Bút&nbsp;chì&nbsp;gỗ&nbsp;nhân&nbsp;vật&nbsp;Akooland&nbsp;Thiên&nbsp;Long&nbsp;TP-GP021/AK</strong>&nbsp;là&nbsp;dòng&nbsp;bút&nbsp;chì&nbsp;2B&nbsp;cao&nbsp;cấp,&nbsp;thiết&nbsp;kế&nbsp;bắt&nbsp;mắt&nbsp;với&nbsp;hình&nbsp;ảnh&nbsp;nhân&nbsp;vật&nbsp;hoạt&nbsp;hình&nbsp;bản&nbsp;quyền&nbsp;Akooland.&nbsp;Sản&nbsp;phẩm&nbsp;có&nbsp;ruột&nbsp;chì&nbsp;2B&nbsp;đậm&nbsp;nét,&nbsp;viết&nbsp;trơn&nbsp;êm,&nbsp;dễ&nbsp;tẩy&nbsp;sạch&nbsp;và&nbsp;khó&nbsp;gãy&nbsp;khi&nbsp;gọt,&nbsp;phù&nbsp;hợp&nbsp;cho&nbsp;học&nbsp;sinh,&nbsp;sinh&nbsp;viên&nbsp;dùng&nbsp;trong&nbsp;học&nbsp;tập,&nbsp;làm&nbsp;bài&nbsp;thi,&nbsp;vẽ&nbsp;và&nbsp;phác&nbsp;thảo.&nbsp;Đây&nbsp;là&nbsp;lựa&nbsp;chọn&nbsp;lý&nbsp;tưởng&nbsp;kết&nbsp;hợp&nbsp;giữa&nbsp;chất&nbsp;lượng&nbsp;bền&nbsp;bỉ&nbsp;và&nbsp;kiểu&nbsp;dáng&nbsp;sinh&nbsp;động,&nbsp;giúp&nbsp;việc&nbsp;học&nbsp;trở&nbsp;nên&nbsp;hứng&nbsp;thú&nbsp;và&nbsp;hiệu&nbsp;quả&nbsp;hơn.</p><p>&nbsp;<strong>Nhận&nbsp;xét&nbsp;về&nbsp;thông&nbsp;số:</strong></p><p>&nbsp;<strong>Độ&nbsp;cứng&nbsp;ruột&nbsp;chì&nbsp;2B:</strong>&nbsp;lý&nbsp;tưởng&nbsp;cho&nbsp;viết&nbsp;chữ,&nbsp;làm&nbsp;bài&nbsp;thi&nbsp;trắc&nbsp;nghiệm,&nbsp;vẽ&nbsp;phác&nbsp;thảo.</p><p>&nbsp;<strong>Đường&nbsp;kính&nbsp;ruột&nbsp;2.42mm:</strong>&nbsp;cho&nbsp;nét&nbsp;rõ&nbsp;ràng,&nbsp;đều&nbsp;màu,&nbsp;dễ&nbsp;kiểm&nbsp;soát&nbsp;khi&nbsp;viết.</p><p>&nbsp;<strong>Chiều&nbsp;dài&nbsp;176mm:</strong>&nbsp;phù&nbsp;hợp&nbsp;tay&nbsp;cầm&nbsp;học&nbsp;sinh&nbsp;và&nbsp;sinh&nbsp;viên,&nbsp;tạo&nbsp;sự&nbsp;thoải&nbsp;mái&nbsp;khi&nbsp;viết&nbsp;lâu.</p><p>&nbsp;<strong>An&nbsp;toàn:</strong>&nbsp;sản&nbsp;xuất&nbsp;tại&nbsp;Việt&nbsp;Nam&nbsp;theo&nbsp;tiêu&nbsp;chuẩn&nbsp;riêng,&nbsp;không&nbsp;chứa&nbsp;chất&nbsp;độc&nbsp;hại.</p>',195,'active'),(4,'8935015801811','Bút sáp màu Queen 18',18000,'/products/sp6.jpg','but-viet','<p><strong>Bút&nbsp;Màu&nbsp;Sáp&nbsp;18&nbsp;Màu&nbsp;-&nbsp;Queen&nbsp;PC-018</strong></p><ul><li>&nbsp;Bút&nbsp;sáp&nbsp;màu&nbsp;Queen&nbsp;đạt&nbsp;tiêu&nbsp;chuẩn&nbsp;an&nbsp;toàn&nbsp;chất&nbsp;lượng,&nbsp;tuyệt&nbsp;đối&nbsp;không&nbsp;gây&nbsp;nguy&nbsp;hiểm&nbsp;tới&nbsp;sức&nbsp;khỏe&nbsp;của&nbsp;bé.&nbsp;Do&nbsp;đó,&nbsp;bố&nbsp;mẹ&nbsp;hoàn&nbsp;toàn&nbsp;có&nbsp;thể&nbsp;yên&nbsp;tâm&nbsp;khi&nbsp;cho&nbsp;con&nbsp;sử&nbsp;dụng&nbsp;sản&nbsp;phẩm.&nbsp;Bút&nbsp;có&nbsp;mực&nbsp;ra&nbsp;đều&nbsp;màu,&nbsp;phản&nbsp;quang&nbsp;tốt&nbsp;giúp&nbsp;màu&nbsp;sắc&nbsp;tươi&nbsp;sáng&nbsp;hơn,&nbsp;nhờ&nbsp;đó&nbsp;các&nbsp;tác&nbsp;phẩm&nbsp;của&nbsp;bé&nbsp;trở&nbsp;nên&nbsp;thật&nbsp;sinh&nbsp;động,&nbsp;bắt&nbsp;mắt.</li><li>&nbsp;Sản&nbsp;phẩm&nbsp;có&nbsp;thiết&nbsp;kế&nbsp;vừa&nbsp;tay,&nbsp;giúp&nbsp;bé&nbsp;cầm&nbsp;nắm&nbsp;và&nbsp;tô&nbsp;màu&nbsp;dễ&nbsp;dàng.&nbsp;Thêm&nbsp;vào&nbsp;đó,&nbsp;bút&nbsp;khá&nbsp;nhỏ&nbsp;gọn&nbsp;nên&nbsp;bé&nbsp;có&nbsp;thể&nbsp;mang&nbsp;theo&nbsp;và&nbsp;tô&nbsp;màu&nbsp;ở&nbsp;bất&nbsp;cứ&n